class Solution {
    public String capitalizeTitle(String title){
        String[] words=title.toLowerCase().split(" ");
        for(int i=0;i<words.length;i++)if(words[i].length()>2)words[i]=Character.toUpperCase(words[i].charAt(0))+words[i].substring(1);
        return String.join(" ",words);
    }
}

